package com.bustramnantes.app.data.local.entity

import androidx.room.Entity
import androidx.room.PrimaryKey

/**
 * Room-persisted recent search entry, capped at 10 rows by [com.bustramnantes.app.data.local.dao.RecentSearchDao.trimToCap]
 * (table `recent_search`).
 *
 * [id] is autogenerated. [type] mirrors [com.bustramnantes.app.domain.model.RecentSearchType]'s
 * `name` (`"STOP"` | `"ADDRESS"`). [stopId] is set for `STOP` entries; [lat]/[lon] are set for
 * `ADDRESS` entries. [searchedAt] is an epoch-ms timestamp.
 */
@Entity(tableName = "recent_search")
data class RecentSearchEntity(
    @PrimaryKey(autoGenerate = true) val id: Long = 0,
    val query: String,
    val type: String,
    val stopId: String?,
    val lat: Double?,
    val lon: Double?,
    val searchedAt: Long,
)
